/// <summary>
/// Batch controller class for Post sales order shipment processing
/// </summary>
class METPickDirectorDataController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>Constuct new object</summary>
/// <param name = "_args">Arguments</param>
/// <param name = "_executionMode">Execution mode</param>
/// <returns>New Controller Object</returns>
public static METPickDirectorDataController construct(Args _args, SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METPickDirectorDataController controller = new METPickDirectorDataController();
    controller.parmExecutionMode(_executionMode);
    controller.parmArgs(_args);

    return controller;
}

/// <summary>
/// New method specifying the service class method to call
/// </summary>
protected void new()
{
    super(classstr(METPickDirectorDataService), methodstr(METPickDirectorDataService, process), SysOperationExecutionMode::Synchronous);
}

/// <summary>
/// Main method
/// </summary>
/// <param name = "_args">Arguments</param>
public static void main(Args _args)
{
    METPickDirectorDataController controller = new METPickDirectorDataController();
    controller.parmArgs(_args);
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions or not.
/// </summary>
/// <returns>
/// If true is returned, the batch task is retryable, otherwise it is not.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Defines caption.
/// </summary>
/// <returns>Caption</returns>
public ClassDescription defaultCaption()
{
    return "Pick director data";
}
